-- 04_big_data.sql : generate 500,000 search-log rows and measure an index.
-- Run in pgAdmin Query Tool on the skillswap database (after 01_schema.sql and 02_seed.sql).
-- All rows are SYNTHETIC (random numbers), generated by generate_series.

-- ---------------------------------------------------------------------------
-- STEP 1: generate 500,000 rows (popular skills are searched more: random()^2 skews the pick)
-- ---------------------------------------------------------------------------
TRUNCATE search_log RESTART IDENTITY;
DROP INDEX IF EXISTS idx_search_skill_time;

WITH u AS (SELECT array_agg(id ORDER BY id) AS ids FROM users),
     s AS (SELECT array_agg(id ORDER BY id) AS ids, array_agg(name ORDER BY id) AS names FROM skills)
INSERT INTO search_log (user_id, skill_id, term, device, searched_at)
SELECT u.ids[1 + floor(x.r_user * cardinality(u.ids))::int],
       s.ids[1 + floor(power(x.r_skill, 2) * cardinality(s.ids))::int],        -- squared: low ids picked more often
       s.names[1 + floor(power(x.r_skill, 2) * cardinality(s.ids))::int],
       (ARRAY['mobile','mobile','mobile','desktop','tablet'])[1 + floor(x.r_dev * 5)::int],   -- mostly phones
       now() - x.r_time * interval '90 days'
FROM (SELECT random() AS r_user, random() AS r_skill, random() AS r_dev, random() AS r_time   -- fresh random numbers for EVERY row
        FROM generate_series(1, 500000)) AS x,
     u, s;

ANALYZE search_log;
SELECT count(*) AS rows_generated FROM search_log;

-- ---------------------------------------------------------------------------
-- STEP 2: the query the app runs ("what was searched most in the last 7 days?")
--         BEFORE any index: PostgreSQL must read all 500,000 rows (Seq Scan).
-- ---------------------------------------------------------------------------
EXPLAIN (ANALYZE, BUFFERS)
SELECT count(*) FROM search_log
WHERE skill_id = 3 AND searched_at >= now() - interval '7 days';

-- ---------------------------------------------------------------------------
-- STEP 3: create the index, refresh statistics
-- ---------------------------------------------------------------------------
CREATE INDEX idx_search_skill_time ON search_log (skill_id, searched_at);
ANALYZE search_log;

-- ---------------------------------------------------------------------------
-- STEP 4: the same query AFTER the index: PostgreSQL jumps straight to the matching rows.
-- ---------------------------------------------------------------------------
EXPLAIN (ANALYZE, BUFFERS)
SELECT count(*) FROM search_log
WHERE skill_id = 3 AND searched_at >= now() - interval '7 days';

-- Write down "Execution Time" from both plans. `npm run db:bigdata` repeats this 5 times
-- and prints the median, so one slow run does not mislead you.
--
-- What the index costs: every INSERT must also update the index (slightly slower writes) and
-- the index uses extra disk space:
SELECT pg_size_pretty(pg_relation_size('search_log'))            AS table_size,
       pg_size_pretty(pg_relation_size('idx_search_skill_time')) AS index_size;
